import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import ThoughtSpotShell from './components/ThoughtSpotShell';
import { TierProvider } from './config/TierContext';
import Sidebar, { SIDEBAR_WIDTH } from './components/NavHeader';
import TopHeader from './components/TopHeader';
import DashboardHome from './pages/DashboardHome';
import SearchPage from './pages/SearchPage';
import PlaceholderPage from './pages/PlaceholderPage';
import Analytics from './pages/Analytics';
import LiveboardTabPage from './pages/LiveboardTabPage';
import './App.css';

function App() {
  return (
    <TierProvider>
      <ThoughtSpotShell>
        <Router>
          <div className="App" style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#1D3FA8' }}>
            <Sidebar />
            <div
              style={{
                marginLeft: SIDEBAR_WIDTH,
                flex: 1,
                minHeight: '100vh',
                display: 'flex',
                flexDirection: 'column',
              }}
            >
              <TopHeader />
              <main style={{ flex: '1 1 auto', width: '100%', minWidth: 0, display: 'flex', flexDirection: 'column' }}>
                <Routes>
                  <Route path="/" element={<Navigate to="/dashboard" replace />} />
                  <Route path="/dashboard" element={<DashboardHome />} />
                  <Route
                    path="/performance"
                    element={
                      <LiveboardTabPage
                        title="Performance & Ranking"
                        description="Top vehicles by delivery count and driver rankings over the last 30 days."
                        tabId="b05e15ee-aff3-4609-ae4c-46db06b28ac6"
                      />
                    }
                  />
                  <Route
                    path="/time-development"
                    element={
                      <LiveboardTabPage
                        title="Time Development"
                        description="Sum of delays per delivery ranked worst-first, total pumped concrete volume over time, shown daily and weekly."
                        tabId="c19dfa82-ba9d-4136-9317-eb941558f081"
                      />
                    }
                  />
                  <Route
                    path="/quality"
                    element={
                      <LiveboardTabPage
                        title="Quality & Failures"
                        description="Unsuccessful deliveries, failure reason breakdown, and delivery note comments including special services and site issues."
                        tabId="a4164f3d-9f06-4aa3-9725-3e179efc474f"
                      />
                    }
                  />
                  <Route
                    path="/geography"
                    element={
                      <LiveboardTabPage
                        title="Geography & Customers"
                        description="Orders by delivery postal code (PLZ) mapped across Germany, regional demand concentration, and construction site activity."
                        tabId="8701338d-ab38-428e-8752-0c27e3462b3e"
                      />
                    }
                  />
                  <Route path="/search" element={<SearchPage />} />
                  <Route
                    path="/pricing"
                    element={<PlaceholderPage title="Revenue & Billing" description="Billed volume per period, revenue per driver and plant, and pricing data across ready-mix concrete, bulk goods, and waste management." />}
                  />
                  <Route path="/knowledge-hub" element={<PlaceholderPage title="Knowledge Hub" />} />
                </Routes>
              </main>
            </div>
          </div>
        </Router>
      </ThoughtSpotShell>
    </TierProvider>
  );
}

export default App;
